    const threatDistance = Math.hypot(lat - newThreat.lat, lng - newThreat.lng);
    const moveFactor = 0.005 / (threatDistance + 0.001);
    const newLat = lat - (lat - newThreat.lat) * moveFactor + /* safe zone attraction */;
    return [newLat, newLng, intensity];
  });
  setHeatmapData(newHeatmapData);
};
```

